<?php declare(strict_types=1);use FastWebsite\Core\View;?>
<section class="page-heading department-heading"><div class="shell"><p class="eyebrow"><?=View::escape(View::setting($siteContent??[],'events.eyebrow','What is happening'))?></p><h1><?=View::escape(View::setting($siteContent??[],'events.title','Events'))?></h1></div></section><section class="section"><div class="shell"><?php if($items===[]):?><div class="public-empty"><p><?=View::escape(View::setting($siteContent??[],'events.empty','Published events will appear here.'))?></p></div><?php else:?><div class="department-card-grid"><?php foreach($items as$i):?><article class="department-card"><div><p class="eyebrow"><?=View::escape(date('j M Y, H:i',strtotime($i['starts_at'])))?></p><h2><a href="<?=View::escape($baseUrl)?>events/<?=View::escape($i['slug'])?>"><?=View::escape($i['title'])?></a></h2><p><?=View::escape($i['summary']??'')?></p><small><?=View::escape($i['venue_name']??trim(($i['campus']??'').' '.($i['building']??'')))?></small></div></article><?php endforeach;?></div><?php endif;?></div></section>
